class string_buf
{
public:
    int char_length;
};

class stringx
{
    char *chars;
    string_buf *my_buf;

public:
    stringx();
    explicit stringx(int i);
    ~stringx();
    void make_room(int n);
    stringx &append(const char *s, int n);
    stringx &append(const stringx &s);
    const char *data() const { return chars; }

    friend stringx operator+(const char *lhs, const stringx &rhs);
};

extern "C" int strlen(const char *);

inline stringx operator+(const char *lhs, const stringx &rhs)
{
    stringx foo;
    int len = strlen(lhs);
    foo.make_room(len + rhs.my_buf->char_length);
    foo.append(lhs, len);
    foo.append(rhs);
    return foo;
}

